import test from 'node:test';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {readFile} from 'node:fs/promises';
import {createAllianceAvatarStorage} from '../lib/alliance-avatar-storage.mjs';
import {validatedDerivative} from '../lib/alliance-avatar-runtime/limits.mjs';

// Synthetic pixel generated by the existing pinned Sharp package, not a member
// file; all requests are in-memory stubs. No native package needed by this test.
const png=Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAACXBIWXMAAAPoAAAD6AG1e1JrAAAADUlEQVQImWMQjG34DwADXwHuQa7szAAAAABJRU5ErkJggg==','base64');
const profileId='11111111-1111-4111-8111-111111111111';
const objectId='22222222-2222-4222-8222-222222222222';
const providerId='33333333-3333-4333-8333-333333333333';
const bucket='alliance-member-images-v1';
const key=`v1/${profileId}/${objectId}.png`;
const origin='https://abcdefghijklmnopqrst.supabase.co';
const apiKey='sb_publishable_'+'synthetic'.repeat(4),bearerToken='syntheticHeader.syntheticClaims.syntheticSignature';
const derivative=()=>({bytes:new Uint8Array(png),width:1,height:1,mime:'image/png'});
const input=()=>({profileId,objectId,derivative:derivative()});
const record=()=>({profileId,objectId,key,providerId,bytes:png.length,width:1,height:1,mime:'image/png',sha256:createHash('sha256').update(png).digest('hex')});
const json=(value,status=200)=>new Response(JSON.stringify(value),{status,headers:{'Content-Type':'application/json'}});
const binary=(bytes=png,headers={})=>new Response(bytes,{headers:{'Content-Type':'image/png',...headers}});
const ack=()=>json({Key:bucket+'/'+key,Id:providerId});
const missing=()=>json({code:'NoSuchKey',message:'fixture'},404);
const allow=async()=>true;
function fixture(run,options={}){
  const calls=[];
  const gateway=createAllianceAvatarStorage({enabled:true,origin,apiKey,bearerToken,...options,fetcher:async(url,init)=>{
    calls.push({url,init});return run?run(url,init,calls.length):init.method==='POST'?ack():binary();
  }});
  return {gateway,calls};
}
const tick=()=>new Promise(resolve=>setImmediate(resolve));

test('fixture is a valid bounded derivative',()=>assert.equal(validatedDerivative({ok:true,...derivative()}).bytes.length,png.length));
test('disabled and non-boolean activation cannot touch a provider or policy',async()=>{
  let touched=0;
  for(const enabled of [undefined,false,'true',1]){
    const g=createAllianceAvatarStorage({enabled,fetcher:()=>{touched++;},timeoutMs:20});
    assert.equal((await g.upload(input())).state,'unavailable');
    assert.equal((await g.read(record(),{authorize:()=>{touched++;}})).state,'unavailable');
    assert.equal((await g.remove(record(),{writeSettled:true,authorize:()=>{touched++;}})).state,'unavailable');
  }assert.equal(touched,0);
});
test('configuration refuses alternate origins, URL secrets, malformed credentials and unbounded waits',()=>{
  for(const bad of [origin+'/',origin+'?key=x',origin.replace('https:','http:'),'https://evil.example',origin+'.evil.example'])assert.throws(()=>fixture(null,{origin:bad}));
  for(const bad of ['one','abc\r\nInjected: x','Bearer '+bearerToken])assert.throws(()=>fixture(null,{bearerToken:bad}));
  for(const bad of [0,-1,8001,1.5,NaN])assert.throws(()=>fixture(null,{timeoutMs:bad}));
  assert.throws(()=>fixture(null,{apiKey:'key with spaces'}));
});
test('bad IDs, paths and invalid derivatives are refused before dispatch',async()=>{
  const f=fixture();
  for(const bad of [{...input(),profileId:'../../other'},{...input(),objectId:'https://evil.example'},{...input(),derivative:{...derivative(),mime:'image/jpeg'}},{...input(),derivative:{...derivative(),width:257}},{...input(),derivative:{...derivative(),bytes:new Uint8Array(307201)}}])assert.equal((await f.gateway.upload(bad)).state,'not_started');
  assert.equal(f.calls.length,0);
});
test('immutable upload binds provider key/id and verifies full bytes before success',async()=>{
  const f=fixture();const result=await f.gateway.upload({...input(),key:'browser/key',url:'https://evil.example'});
  assert.deepEqual(result,{state:'stored',writeSettled:true,verified:true,receipt:record()});
  assert.deepEqual(f.calls.map(c=>c.init.method),['POST','GET']);
  for(const c of f.calls){assert.equal(c.url,origin+'/storage/v1/object/'+bucket+'/'+key);assert.equal(c.init.redirect,'error');assert.equal(c.init.credentials,'omit');assert.equal(c.init.cache,'no-store');assert.equal(c.init.headers.Authorization,'Bearer '+bearerToken);}
  assert.equal(f.calls[0].init.headers['x-upsert'],'false');assert.equal(f.calls[0].init.headers['Content-Type'],'image/png');
  assert.equal(f.calls[0].init.headers['Cache-Control'],'max-age=0');assert.ok(Object.isFrozen(result.receipt));
  assert.doesNotMatch(JSON.stringify(result),/syntheticHeader|sb_publishable|https:/);
});
test('mutable caller bytes are copied before the request yields',async()=>{
  let release;const wait=new Promise(r=>release=r);
  const f=fixture(async(_url,init)=>{if(init.method==='POST'){await wait;assert.deepEqual(Buffer.from(init.body),png);return ack();}return binary();});
  const value=input();const pending=f.gateway.upload(value);value.derivative.bytes.fill(0);release();assert.equal((await pending).state,'stored');
});
test('pre-cancellation makes zero requests and cannot claim an uncertain write',async()=>{
  const f=fixture(),c=new AbortController();c.abort();
  assert.equal((await f.gateway.upload(input(),{signal:c.signal})).state,'not_started');assert.equal(f.calls.length,0);
});
test('mismatched/malformed/oversized acknowledgements quarantine without verification GET',async()=>{
  for(const response of [()=>json({Key:bucket+'/other',Id:providerId}),()=>json({Key:bucket+'/'+key,Id:'other'}),()=>new Response('not-json',{headers:{'Content-Type':'application/json'}}),()=>json({Key:bucket+'/'+key,Id:providerId,huge:'x'.repeat(16384)})]){
    const f=fixture(()=>response());const result=await f.gateway.upload(input());assert.equal(result.state,'unknown');assert.equal(result.writeSettled,false);assert.equal(f.calls.length,1);
  }
});
test('HTTP conflicts, errors and redirects never retry or imply no write',async()=>{
  for(const status of [301,400,401,403,404,409,429,500]){
    const f=fixture(()=>json({secret:'DO-NOT-EXPOSE'},status));const result=await f.gateway.upload(input());assert.equal(result.state,'unknown');assert.equal(f.calls.length,1);assert.doesNotMatch(JSON.stringify(result),/DO-NOT/);
  }
});
test('lost upload response is unknown, even if a separate observer could find the file',async()=>{
  const f=fixture(()=>{throw Error('URL OR SECRET MUST NOT ESCAPE');});
  assert.deepEqual(await f.gateway.upload(input()),{state:'unknown',writeSettled:false});assert.equal(f.calls.length,1);
});
test('successful upload followed by bad checksum/type/length stays settled but unpublished',async()=>{
  for(const bad of [()=>binary(Buffer.concat([png,Buffer.from([0])])),()=>binary(Buffer.alloc(png.length)),()=>new Response(png,{headers:{'Content-Type':'text/html'}}),()=>binary(png,{'Content-Length':'1'})]){
    const f=fixture((_u,init)=>init.method==='POST'?ack():bad());const result=await f.gateway.upload(input());
    assert.equal(result.state,'stored_unverified');assert.equal(result.writeSettled,true);assert.equal(result.verified,false);assert.deepEqual(result.receipt,record());assert.equal(f.calls.length,2);
  }
});
test('a missing verification object does not lose matching upload acknowledgement',async()=>{
  const f=fixture((_u,init)=>init.method==='POST'?ack():missing());const result=await f.gateway.upload(input());assert.equal(result.state,'stored_unverified');assert.equal(result.writeSettled,true);
});
test('deadline returns despite a non-cooperative fetch; late response cannot start GET',async()=>{
  let release,cancelled=0;const wait=new Promise(r=>release=r);
  const f=fixture(async()=>{await wait;return {status:200,redirected:false,body:{cancel(){cancelled++;}}};},{timeoutMs:20});
  assert.equal((await f.gateway.upload(input())).state,'unknown');release();await tick();assert.equal(f.calls.length,1);assert.equal(cancelled,1);
});
test('stalled body is bounded independently of transport cancellation',async()=>{
  let cancelled=0;
  const f=fixture(()=>new Response(new ReadableStream({pull(){return new Promise(()=>{});},cancel(){cancelled++;}}),{headers:{'Content-Type':'application/json'}}),{timeoutMs:20});
  assert.equal((await f.gateway.upload(input())).state,'unknown');await tick();assert.equal(cancelled,1);assert.equal(f.calls.length,1);
});
test('cancellation after matching acknowledgement retains settlement but refuses publication',async()=>{
  const c=new AbortController();const f=fixture((_u,init)=>{if(init.method==='POST')return ack();c.abort();return binary();});
  const r=await f.gateway.upload(input(),{signal:c.signal});assert.equal(r.state,'stored_unverified');assert.equal(r.writeSettled,true);
});
test('private reads require a valid durable record and an explicit current-visibility check',async()=>{
  const f=fixture();for(const r of [{...record(),key:'v1/other'},{...record(),sha256:'invalid'},{...record(),providerId:'other'}])assert.equal((await f.gateway.read(r,{authorize:allow})).state,'unavailable');
  assert.equal((await f.gateway.read(record())).state,'unavailable');
  for(const authorize of [async()=>false,async()=>({listed:true}),async()=>{throw Error('private');}])assert.equal((await f.gateway.read(record(),{authorize})).state,'unavailable');
  assert.equal(f.calls.length,0);
});
test('private read rechecks authorization and returns only no-store PNG bytes',async()=>{
  const f=fixture();let checks=0;const result=await f.gateway.read(record(),{authorize:async value=>{assert.ok(Object.isFrozen(value));assert.deepEqual(value,record());checks++;return true;}});
  assert.equal(checks,2);assert.equal(f.calls.length,1);assert.equal(result.state,'readable');
  assert.deepEqual(Buffer.from(await result.response.arrayBuffer()),png);
  assert.equal(result.response.headers.get('cache-control'),'private, no-store');assert.equal(result.response.headers.get('netlify-cdn-cache-control'),'no-store');assert.equal(result.response.headers.get('vary'),'Cookie');assert.equal(result.response.headers.get('x-content-type-options'),'nosniff');assert.equal(result.response.headers.get('referrer-policy'),'no-referrer');assert.equal(result.response.headers.get('content-type'),'image/png');assert.equal(result.response.headers.get('set-cookie'),null);
});
test('unlisting, membership loss or pointer change during fetch discards bytes',async()=>{
  const f=fixture();let checks=0;const result=await f.gateway.read(record(),{authorize:async()=>++checks===1});assert.deepEqual(result,{state:'unavailable'});assert.equal(checks,2);assert.equal(f.calls.length,1);
});
test('private read and policy callback stalls have a deadline',async()=>{
  const f=fixture(()=>new Promise(()=>{}),{timeoutMs:20});assert.equal((await f.gateway.read(record(),{authorize:allow})).state,'unavailable');assert.equal(f.calls.length,1);
  const g=fixture(null,{timeoutMs:20});assert.equal((await g.gateway.read(record(),{authorize:()=>new Promise(()=>{})})).state,'unavailable');assert.equal(g.calls.length,0);
});
test('unsettled/current/unauthorized files cannot reach deletion',async()=>{
  const f=fixture();for(const options of [{},{writeSettled:'true',authorize:allow},{writeSettled:true},{writeSettled:true,authorize:async()=>false}])assert.equal((await f.gateway.remove(record(),options)).state,'not_started');assert.equal(f.calls.length,0);
});
test('deletion uses one exact object key and matching receipt before checking absence',async()=>{
  const f=fixture((_u,init)=>init.method==='DELETE'?json([{id:providerId,name:key}]):missing());
  const r=await f.gateway.remove(record(),{writeSettled:true,authorize:allow});assert.equal(r.state,'deleted');assert.deepEqual(r.receipt,record());assert.equal(f.calls.length,2);assert.equal(f.calls[0].url,origin+'/storage/v1/object/'+bucket);assert.deepEqual(JSON.parse(f.calls[0].init.body),{prefixes:[key]});assert.equal(f.calls[1].url,origin+'/storage/v1/object/'+bucket+'/'+key);
});
test('empty, extra or mismatched deletion response never releases capacity',async()=>{
  for(const body of [[],[{id:providerId,name:'other'}],[{id:objectId,name:key}],[{id:providerId,name:key},{id:providerId,name:key}],{message:'ok'}]){
    const f=fixture(()=>json(body));assert.equal((await f.gateway.remove(record(),{writeSettled:true,authorize:allow})).state,'unknown');assert.equal(f.calls.length,1);
  }
});
test('HTTP 404 alone, missing bucket, access errors and legacy ambiguous missing are not absence proof',async()=>{
  for(const missingResponse of [()=>new Response('not found',{status:404}),()=>json({code:'NoSuchBucket'},404),()=>json({code:'AccessDenied'},403),()=>json({code:'not_found'},404),()=>json({code:'NoSuchKey'},400),()=>binary()]){
    const f=fixture((_u,init)=>init.method==='DELETE'?json([{id:providerId,name:key}]):missingResponse());assert.equal((await f.gateway.remove(record(),{writeSettled:true,authorize:allow})).state,'unknown');assert.equal(f.calls.length,2);
  }
});
test('lost delete acknowledgement is unknown with no automatic follow-up or retry',async()=>{
  const f=fixture(()=>{throw Error('PRIVATE');});assert.deepEqual(await f.gateway.remove(record(),{writeSettled:true,authorize:allow}),{state:'unknown'});assert.equal(f.calls.length,1);
});
test('oversized streaming bytes are rejected without trusting Content-Length',async()=>{
  const f=fixture((_u,init)=>init.method==='POST'?ack():new Response(new ReadableStream({start(c){c.enqueue(new Uint8Array(307201));c.close();}}),{headers:{'Content-Type':'image/png'}}));assert.equal((await f.gateway.upload(input())).state,'stored_unverified');assert.equal(f.calls.length,2);
});
test('a redirected response cannot be accepted even when an injected fetch ignores redirect policy',async()=>{
  const f=fixture(()=>({status:200,redirected:true,body:{cancel(){}}}));assert.equal((await f.gateway.upload(input())).state,'unknown');assert.equal(f.calls.length,1);
});
test('split binary streams are fully checked and accepted without Content-Length',async()=>{
  const f=fixture((_u,init)=>init.method==='POST'?ack():new Response(new ReadableStream({start(c){c.enqueue(png.subarray(0,20));c.enqueue(png.subarray(20));c.close();}}),{headers:{'Content-Type':'image/png'}}));assert.equal((await f.gateway.upload(input())).state,'stored');
});
test('abort during a private visibility check cannot dispatch after a late authorization result',async()=>{
  let release;const wait=new Promise(r=>release=r),c=new AbortController();const f=fixture();
  const pending=f.gateway.read(record(),{signal:c.signal,authorize:()=>wait});c.abort();assert.equal((await pending).state,'unavailable');release(true);await tick();assert.equal(f.calls.length,0);
});
test('delete timeout does not dispatch an absence probe after its late acknowledgement',async()=>{
  let release;const wait=new Promise(r=>release=r);const f=fixture(async()=>{await wait;return json([{id:providerId,name:key}]);},{timeoutMs:20});
  assert.equal((await f.gateway.remove(record(),{writeSettled:true,authorize:allow})).state,'unknown');release();await tick();assert.equal(f.calls.length,1);
});
test('reentrant reads snapshot a durable receipt before an asynchronous policy check',async()=>{
  let release,checked=false;const wait=new Promise(r=>release=r);const f=fixture();const value=record();
  const pending=f.gateway.read(value,{authorize:async()=>{if(!checked){checked=true;await wait;}return true;}});
  value.key='other';value.sha256='0'.repeat(64);value.objectId=profileId;release();assert.equal((await pending).state,'readable');assert.equal(f.calls[0].url,origin+'/storage/v1/object/'+bucket+'/'+key);
});
test('candidate has no mounted route, environment access, public URL, signed URL, listing or retry loop',async()=>{
  const source=await readFile(new URL('../lib/alliance-avatar-storage.mjs',import.meta.url),'utf8');
  assert.doesNotMatch(source,/process\.env|createSignedUrl|getPublicUrl|\/object\/(?:public|sign|list)|export default/);
  assert.equal(Object.keys(createAllianceAvatarStorage()).sort().join(','),'read,remove,upload');
});
